function line(pts,p,w,pr)
 local b=brush{kind='round',width=w,point=0.12,stiffness=0.7}
 b:load(p,0.98)
 b:stroke(pts,{pressure={pr or 0.86,pr or 0.86},ramps={0.015,0.025},shake=0.1,orient='across'})
end
function patch(pts,p,a,c)
